WITH filtered_departments AS (SELECT * FROM departments WHERE budget > 3017000 OR dept_name NOT IN ('Engineering', 'Marketing', 'HR')), location_group_summary AS (SELECT CASE WHEN location IN ('Chiang Mai', 'London') THEN 'core' ELSE 'other' END AS location_group, ROUND(STDDEV(budget), 2) AS stddev_budget, COUNT(CASE WHEN location = 'Bangkok' THEN 1 END) AS bangkok_count FROM filtered_departments GROUP BY CASE WHEN location IN ('Chiang Mai', 'London') THEN 'core' ELSE 'other' END) SELECT location_group, stddev_budget, bangkok_count FROM location_group_summary ORDER BY location_group;
